import React, { useState, useEffect } from 'react';
import ExcursionCard from '../../components/Card/ExcursionCard';
import Filter from '../../components/Filter/Filter';
import { excursions } from '../../Data/excursions';
import './CatalogPage.css';

const filtersData = {
  Рейтинг: [5, 4, 3, 2, 1],
  Страна: ['Египет', 'Турция'],
  Категория: ['История', 'Культура'],
  Тэги: ['Пешая', 'Автобусная', 'Индивидуальная']
};

const CatalogPage = () => {
  const [filters, setFilters] = useState({});
  const [favorites, setFavorites] = useState(new Set());
  const [cart, setCart] = useState(new Set());


  // ⛔️ временно mock, потом будет API
  useEffect(() => {
    setFavoriteIds([1, 3]); // избранные tour_id
    setCartIds([2]);        // в корзине tour_id
  }, []);

  const toggleFavorite = (tourId) => {
    setFavoriteIds(prev =>
      prev.includes(tourId)
        ? prev.filter(id => id !== tourId)
        : [...prev, tourId]
    );

    // 👉 позже: POST / DELETE favorite_tour
  };

  const toggleCart = (tourId) => {
    setCartIds(prev =>
      prev.includes(tourId)
        ? prev.filter(id => id !== tourId)
        : [...prev, tourId]
    );

    // 👉 позже: POST / DELETE cart_items
  };

  const applyFilters = (items) => {
    return items.filter((excursion) => {
      if (filters['Рейтинг']?.size) {
        if (!filters['Рейтинг'].has(Math.floor(excursion.rating))) {
          return false;
        }
      }

      if (filters['Страна']?.size) {
        if (!filters['Страна'].has(excursion.country)) {
          return false;
        }
      }

      if (filters['Категория']?.size) {
        if (!filters['Категория'].has(excursion.category)) {
          return false;
        }
      }

      if (filters['Тэги']?.size) {
        const hasAll = [...filters['Тэги']].every(tag =>
          excursion.tags?.includes(tag)
        );
        if (!hasAll) return false;
      }

      return true;
    });
  };

  const filteredExcursions = applyFilters(excursions);

  return (
    <div className="catalog-wrapper">
      <div className="layout-catalog">
        <Filter filters={filtersData} onChange={setFilters} />

        <main className="content-catalog">
          <div className="catalog-grid">
            {filteredExcursions.map((excursion) => (
              <ExcursionCard
                key={excursion.id}
                excursion={excursion}
                isFavorite={favoriteIds.has(excursion.id)}
                inCart={cartIds.has(excursion.id)}
                onToggleFavorite={toggleFavorite}
                onToggleCart={toggleCart}
              />
            ))}
          </div>

          {filteredExcursions.length === 0 && (
            <div className="no-results">
              Ничего не найдено по выбранным фильтрам
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default CatalogPage;
